package vn.covie.inventory.model;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="inventory_reservations") public class InventoryReservationEntity { @Id private UUID id; @Column(name="location_variant_id",nullable=false) private UUID locationVariantId; @Column(name="order_id",nullable=false) private UUID orderId; @Column(name="order_item_id",nullable=false) private UUID orderItemId; @Column(nullable=false) private long quantity; @Enumerated(EnumType.STRING) @Column(name="reservation_status",nullable=false) private InventoryReservationStatus reservationStatus; @Column(name="expires_at") private Instant expiresAt; @Column(name="created_at",nullable=false) private Instant createdAt; @Column(name="committed_at") private Instant committedAt; @Column(name="released_at") private Instant releasedAt; protected InventoryReservationEntity(){} public static InventoryReservationEntity active(UUID id,UUID variant,UUID order,UUID item,long qty,Instant now){InventoryReservationEntity r=new InventoryReservationEntity();r.id=id;r.locationVariantId=variant;r.orderId=order;r.orderItemId=item;r.quantity=qty;r.reservationStatus=InventoryReservationStatus.ACTIVE;r.createdAt=now;return r;} public void markReleased(Instant now){if(reservationStatus==InventoryReservationStatus.ACTIVE){reservationStatus=InventoryReservationStatus.RELEASED;releasedAt=now;}} public void markCommitted(Instant now){if(reservationStatus==InventoryReservationStatus.ACTIVE){reservationStatus=InventoryReservationStatus.COMMITTED;committedAt=now;}} public UUID getId(){return id;} public UUID getLocationVariantId(){return locationVariantId;} public UUID getOrderId(){return orderId;} public UUID getOrderItemId(){return orderItemId;} public long getQuantity(){return quantity;} public InventoryReservationStatus getReservationStatus(){return reservationStatus;} }
